import React, { useEffect, useState } from 'react';
import { useTranslation } from '../hooks/useTranslation';

const SobreMim = () => {
  const { t } = useTranslation();
  const [displayName, setDisplayName] = useState('');
  const [isTypingComplete, setIsTypingComplete] = useState(false);

  useEffect(() => {
    const name = t('hero_name');
    let index = 0;
    let timeoutId;

    const typeNextChar = () => {
      if (index < name.length) {
        setDisplayName(name.substring(0, index + 1));
        index++;
        timeoutId = setTimeout(typeNextChar, 80);
      } else {
        setIsTypingComplete(true);
      }
    };

    typeNextChar();

    return () => clearTimeout(timeoutId);
  }, [t]);

  return (
    <section id="hero" className="hero">
      <div className="hero-background-image"></div>
      <div className="hero-overlay"></div>
      
      <div className="hero-availability-badge">
        <i className="bi bi-check-circle-fill"></i>
        <span>Disponível para projetos</span>
      </div>

      <div className="hero-content-left" data-aos="fade-up">
        <div className="hero-top" data-aos="fade-up" data-aos-delay="100">
          <div className="hero-greeting">{t('hero_title')}</div>
        </div>

        <div className="hero-info" data-aos="fade-up" data-aos-delay="200">
          <div className="hero-name-wrapper">
            <span className="hero-prefix">{t('hero_prefix')}</span>
            <h1 className="hero-name">
              {displayName}
              <span className={`hero-cursor ${isTypingComplete ? 'hidden' : ''}`}>|</span>
            </h1>
          </div>
          <p className="hero-role">{t('hero_role')}</p>
          <div className="hero-tags" data-aos="fade-up" data-aos-delay="300">
            <span>Front-end</span>
            <span>Back-end</span>
            <span>Métodos Ágeis</span>
            <span>UI/UX</span>
          </div>
        </div>

        <div className="hero-social" data-aos="fade-up" data-aos-delay="400">
          <a href="https://github.com/MatheusAbib" target="_blank" rel="noopener noreferrer">
            <i className="bi bi-github"></i>
          </a>
          <a href="https://www.linkedin.com/in/matheusabib/" target="_blank" rel="noopener noreferrer">
            <i className="bi bi-linkedin"></i>
          </a>
          <a href="https://wa.me/11975072008" target="_blank" rel="noopener noreferrer">
            <i className="bi bi-whatsapp"></i>
          </a>
        </div>

        <div className="hero-scroll-indicator">
          <span>Scroll</span>
          <i className="bi bi-chevron-down"></i>
        </div>
      </div>
    </section>
  );
};

export default SobreMim;
